// @generated by:gauntlet run:godseye-e08-independent-gauntlet

import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type E08UsageFixture, e08UsageFixture, unknownOutcome } from "./helpers/e08-usage.js";
import { required } from "./helpers/e08-values.js";

describe("E08 invoice identities and conservative obligations", () => {
  let f: E08UsageFixture;
  beforeEach(async () => {
    f = await e08UsageFixture();
  });
  afterEach(async () => {
    await f.finish();
    await f.store.close();
  });
  const invoice = (attemptId: string | null = null) => ({
    projectId: f.project.id,
    provider: "openai" as const,
    currency: "USD" as const,
    invoiceId: "fixture-invoice-1",
    source: "fixture" as const,
    periodStart: new Date(f.clock.now().getTime() - 86400000).toISOString(),
    periodEnd: new Date(f.clock.now().getTime() + 86400000).toISOString(),
    lines: [{ lineId: "line-1", attemptId, amountMicros: 50 }],
  });

  it("T-AC-804 reconciles exact attempt identities without refunding Foundation charges", async () => {
    await f.start();
    const row = await f.record({
      ...unknownOutcome,
      state: "succeeded",
      providerReportedMicros: 80,
    });
    if (!row) throw new Error("Expected usage attempt");
    await f.finish();
    const before = await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id);
    expect(before.spentMicros).toBeGreaterThan(0);
    const imported = await f.usage.importInvoice(f.freshOwner(), invoice(row.id), randomUUID());
    const result = await f.usage.reconcileInvoice(f.freshOwner(), imported.id, randomUUID());
    const after = await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id);
    expect(result.reconciliations).toContainEqual(
      expect.objectContaining({ matched: 1, unmatched: 0, discrepancyMicros: -30 }),
    );
    expect(after.spentMicros).toBe(before.spentMicros);
    expect(after.reservedMicros).toBe(before.reservedMicros);
  });

  it("T-AC-804 preserves invoice identity across new request keys and refuses changed line values", async () => {
    const first = await f.usage.importInvoice(f.freshOwner(), invoice(), randomUUID());
    const replay = await f.usage.importInvoice(f.freshOwner(), invoice(), randomUUID());
    expect(replay.id).toBe(first.id);
    await expect(
      f.usage.importInvoice(
        f.freshOwner(),
        { ...invoice(), lines: [{ lineId: "line-1", attemptId: null, amountMicros: 51 }] },
        randomUUID(),
      ),
    ).rejects.toThrow();
    expect((await f.usage.overview(f.freshOwner())).invoices).toHaveLength(1);
  });

  it("T-AC-804 cannot import an attempt from another project or duplicate invoice line identity", async () => {
    const row = await f.record();
    if (!row) throw new Error("Expected usage attempt");
    await expect(
      f.usage.importInvoice(
        f.freshOwner(),
        { ...invoice(row.id), projectId: f.secondProject.id },
        randomUUID(),
      ),
    ).rejects.toThrow();
    await expect(
      f.usage.importInvoice(
        f.freshOwner(),
        { ...invoice(), lines: [required(invoice().lines[0]), required(invoice().lines[0])] },
        randomUUID(),
      ),
    ).rejects.toThrow();
  });

  it("T-AC-804 leaves unmatched lines visible instead of attributing invoice totals to a run", async () => {
    const imported = await f.usage.importInvoice(f.freshOwner(), invoice(), randomUUID());
    const result = await f.usage.reconcileInvoice(f.freshOwner(), imported.id, randomUUID());
    expect(result.reconciliations).toContainEqual(
      expect.objectContaining({ matched: 0, unmatched: 1 }),
    );
    expect((await f.usage.overview(f.freshOwner())).summary.estimatedMicros).toBeNull();
  });
});
